import { createHash } from "node:crypto";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const variants = [
  { id: "variant-a", ordinal: 1, source: "inputs/a.txt" },
  { id: "variant-b", ordinal: 2, source: "inputs/b.txt" },
];

const projectRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const artifacts = await Promise.all(
  variants.map(async ({ id, ordinal, source }) => {
    const bytes = await readFile(resolve(projectRoot, source));

    return {
      id,
      ordinal,
      source,
      byteLength: bytes.byteLength,
      sha256: createHash("sha256").update(bytes).digest("hex").toUpperCase(),
    };
  }),
);

artifacts.sort((left, right) => left.ordinal - right.ordinal);

const outputPath = resolve(projectRoot, "data/artifacts.json");
await mkdir(dirname(outputPath), { recursive: true });
await writeFile(outputPath, `${JSON.stringify(artifacts, null, 2)}\n`);

